function mapMauticForm(body, expectedFormId, enableWrites) {
  if (!enableWrites)
    throw new Error("Verify webhook Header authentication before enabling Mautic writes");
  if (
    typeof expectedFormId !== "string" ||
    !expectedFormId ||
    expectedFormId === "YOUR_WORDPRESS_FORM_ID"
  ) {
    throw new Error("Configure the WordPress form ID");
  }
  if (body?.form_id !== expectedFormId) throw new Error("Unexpected WordPress form ID");
  const { Nome: name, "E-mail": email, WhatsApp: mobile } = body;
  if (
    typeof name !== "string" ||
    !name.trim() ||
    name.length > 200 ||
    typeof email !== "string" ||
    email.length > 254 ||
    typeof mobile !== "string" ||
    mobile.length > 80
  ) {
    throw new Error("Expected Nome, E-mail and WhatsApp as form fields");
  }
  const firstName = name
    .trim()
    .replace(/(^|[\s-])(\p{Ll})([\p{L}\p{M}'’]*)/gu, (word, prefix, initial, rest) =>
      /\p{Lu}/u.test(rest) ? word : prefix + initial.toUpperCase() + rest,
    );
  const emailValid =
    !email.includes(" ") &&
    /(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@(\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}]|([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,})/.test(
      email,
    );
  return { fields: { firstname: firstName, email: email.toLowerCase(), mobile }, emailValid };
}
const expectedFormId = "YOUR_WORDPRESS_FORM_ID";
const enableWrites = false;
return [{ json: mapMauticForm($input.first().json.body, expectedFormId, enableWrites) }];

function confirmMauticContact(contact, fields, emailValid) {
  if (!Number.isSafeInteger(contact?.id) || contact.id < 1)
    throw new Error("Mautic did not return a valid Contact ID");
  const returned = contact.fields?.all;
  if (
    !returned ||
    returned.firstname !== fields.firstname ||
    (returned.mobile ?? "") !== fields.mobile ||
    (returned.email !== fields.email &&
      (emailValid || (returned.email != null && returned.email !== "")))
  ) {
    throw new Error(
      "Mautic did not return the contact for this submission. Check the saved record before retrying.",
    );
  }
  return contact.id;
}
const lead = $("Map the form and validate email syntax").first().json;
const contactId = confirmMauticContact($input.first().json, lead.fields, lead.emailValid);
return [{ json: { contactId, emailStatus: "valid_syntax", suppressEmail: !lead.emailValid } }];

function confirmMauticDnc(contact, contactId) {
  if (
    contact?.id !== contactId ||
    !Array.isArray(contact.doNotContact) ||
    !contact.doNotContact.some(
      (entry) => entry?.channel === "email" && [1, 3].includes(Number(entry.reason)),
    )
  ) {
    throw new Error("Mautic did not confirm email Do Not Contact on the saved Contact ID");
  }
  return { contactId, emailStatus: "do_not_contact" };
}
const { contactId } = $("Confirm the saved contact").first().json;
return [{ json: confirmMauticDnc($input.first().json, contactId) }];
